"""
Notification Service for the AI Agent Social Network.
Handles creation, retrieval, and feedback recording for agent notifications.
"""

from __future__ import annotations

import uuid
from datetime import datetime, timezone
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    pass

from app.models import Notification, NotificationFeedback


class NotificationService:
    """Manages agent notifications generated by the relevance routing engine."""

    # ------------------------------------------------------------------
    # Creation
    # ------------------------------------------------------------------

    def create_notifications(
        self,
        db,
        post_id: str,
        routed_agents: list[tuple[str, float]],
    ) -> list[Notification]:
        """Create Notification rows for each (agent_id, relevance_score) pair.

        Args:
            db: SQLAlchemy session.
            post_id: ID of the post that triggered the notifications.
            routed_agents: List of (agent_id, relevance_score) tuples returned
                           by RelevanceRouter.route_post().

        Returns:
            List of persisted Notification objects.
        """
        notifications: list[Notification] = []
        for agent_id, relevance_score in routed_agents:
            notification = Notification(
                id=str(uuid.uuid4()),
                post_id=post_id,
                agent_id=agent_id,
                relevance_score=relevance_score,
                is_read=False,
                created_at=datetime.now(timezone.utc),
            )
            db.add(notification)
            notifications.append(notification)

        db.commit()
        for n in notifications:
            db.refresh(n)

        return notifications

    # ------------------------------------------------------------------
    # Retrieval
    # ------------------------------------------------------------------

    def get_pending_notifications(
        self, db, agent_id: str
    ) -> list[Notification]:
        """Return all unread notifications for a given agent, newest first.

        Args:
            db: SQLAlchemy session.
            agent_id: The agent whose notifications to fetch.

        Returns:
            List of unread Notification objects ordered by created_at descending.
        """
        return (
            db.query(Notification)
            .filter(
                Notification.agent_id == agent_id,
                Notification.is_read == False,  # noqa: E712
            )
            .order_by(Notification.created_at.desc())
            .all()
        )

    # ------------------------------------------------------------------
    # Read / feedback
    # ------------------------------------------------------------------

    def mark_read(self, db, notification_id: str) -> None:
        """Mark a notification as read.

        Args:
            db: SQLAlchemy session.
            notification_id: ID of the notification to mark read.
        """
        notification = (
            db.query(Notification)
            .filter(Notification.id == notification_id)
            .first()
        )
        if notification:
            notification.is_read = True
            db.commit()

    def record_feedback(
        self, db, notification_id: str, did_comment: bool
    ) -> NotificationFeedback | None:
        """Create a NotificationFeedback row to feed the learning loop.

        Args:
            db: SQLAlchemy session.
            notification_id: ID of the notification the feedback relates to.
            did_comment: Whether the agent actually engaged with the post.

        Returns:
            The persisted NotificationFeedback, or None if the notification
            doesn't exist.
        """
        notification = (
            db.query(Notification)
            .filter(Notification.id == notification_id)
            .first()
        )
        if not notification:
            return None

        feedback = NotificationFeedback(
            id=str(uuid.uuid4()),
            notification_id=notification_id,
            did_comment=did_comment,
            created_at=datetime.now(timezone.utc),
        )
        db.add(feedback)
        db.commit()
        db.refresh(feedback)
        return feedback
